import torch


def build(model, path):
    state = torch.load(path)
    backbone = {k: v for k, v in state.items() if "encoder." in k}
    model.load_state_dict(backbone, strict=False)
    for p in model.encoder.parameters():
        p.requires_grad_(False)
    return model
